import pandas as pd

def clean(df):
    df = df.copy()
    df['island'] = df['island'].replace('Bisco', 'Biscoe')
    df['sex'] = df['sex'].str.strip()
    df = df.dropna(subset=['sex'])
    return df

def answer(df):
    df = clean(df)
    return df.groupby('sex')['body_mass_g'].mean().to_dict()
